CREATE OR REPLACE FUNCTION private.org_preview_visible(c jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE allowed_ text[];BEGIN IF private.is_super_admin(auth.uid()) THEN RETURN c;END IF;SELECT coalesce(array_agg(id),'{}') INTO allowed_ FROM org_units WHERE private.org_can(auth.uid(),'org.view',id) OR private.org_can(auth.uid(),'org.assign_staff',id) OR private.org_can(auth.uid(),'org.appoint_manager',id) OR private.org_can(auth.uid(),'org.manage_structure',id); RETURN jsonb_build_object('units',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(c->'units')x WHERE x->>'id'=ANY(allowed_)),'titles',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(c->'titles')x WHERE x->>'unit_id'=ANY(allowed_) OR (x->>'unit_id' IS NULL AND EXISTS(SELECT 1 FROM org_units WHERE id=ANY(allowed_) AND kind=x->>'unit_kind'))),'memberships',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(c->'memberships')x WHERE x->>'unit_id'=ANY(allowed_)),'defaults','[]'::jsonb,'bundles','[]'::jsonb,'grants','[]'::jsonb,'bindings','[]'::jsonb);END $$;
CREATE OR REPLACE FUNCTION public.org_change(_phase text,_revision bigint DEFAULT NULL,_change jsonb DEFAULT NULL,_preview uuid DEFAULT NULL,_confirmation text DEFAULT NULL,_reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record;before_ jsonb;after_ jsonb;units_ jsonb;id_ uuid;rev_ bigint;fingerprint_ text;normalized_ jsonb;BEGIN IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) THEN RAISE EXCEPTION 'Vui lòng đăng nhập lại.';END IF;IF _phase NOT IN ('preview','apply') THEN RAISE EXCEPTION 'Giai đoạn không hợp lệ.';END IF;PERFORM pg_advisory_xact_lock(hashtext('canonical_org'));PERFORM pg_advisory_xact_lock(hashtext('base_org'));PERFORM pg_advisory_xact_lock(hashtext('biz_org_structure'));LOCK TABLE org_units,org_titles,org_assignments,base_org_state,biz_systems,biz_departments,biz_teams,biz_positions,biz_appointments,biz_department_members,biz_team_members,biz_member_affiliations,biz_management_assignments,biz_department_system_history,base_title_role_links IN SHARE ROW EXCLUSIVE MODE;LOCK TABLE profiles,user_roles,app_roles,biz_approval_workflows,biz_access_exceptions IN SHARE MODE;SELECT revision INTO rev_ FROM private.org_control WHERE id FOR UPDATE;before_:=private.org_config();fingerprint_:=private.org_fingerprint();
 IF _phase='preview' THEN IF _revision IS DISTINCT FROM rev_ THEN RAISE EXCEPTION 'Nguồn cơ cấu đã thay đổi; xem trước lại.';END IF;IF jsonb_typeof(_change) IS DISTINCT FROM 'array' OR jsonb_array_length(_change) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Danh sách thay đổi không hợp lệ.';END IF;SELECT jsonb_agg(x||jsonb_build_object('data',coalesce(x->'data','{}')||jsonb_build_object('id',coalesce(nullif(x->'data'->>'id',''),gen_random_uuid()::text))||CASE WHEN x->>'action'='assign' AND nullif(x->'data'->>'starts_at','') IS NULL THEN jsonb_build_object('starts_at',clock_timestamp()) WHEN x->>'action'='end' AND nullif(x->'data'->>'ends_at','') IS NULL THEN jsonb_build_object('ends_at',clock_timestamp()) ELSE '{}'::jsonb END)) INTO normalized_ FROM jsonb_array_elements(_change)x;INSERT INTO private.org_previews(actor_id,revision,baseline,changes,impact,next_transition_at) VALUES(auth.uid(),rev_,fingerprint_,normalized_,'{}',(SELECT min(ts) FROM (SELECT starts_at ts FROM org_assignments UNION ALL SELECT ends_at FROM org_assignments)x WHERE ts>clock_timestamp())) RETURNING id INTO id_;BEGIN INSERT INTO private.org_execution(transaction_id,actor_id,preview_id) VALUES(txid_current(),auth.uid(),id_);units_:=private.org_commands_v2(normalized_);after_:=private.org_config();RAISE EXCEPTION USING ERRCODE='ZX001',MESSAGE='rollback preview';EXCEPTION WHEN SQLSTATE 'ZX001' THEN NULL;END;UPDATE private.org_previews SET impact=jsonb_build_object('before',before_,'after',after_,'signature',private.org_effect_signature(after_,normalized_),'units',units_) WHERE id=id_;RETURN jsonb_build_object('id',id_,'revision',rev_,'impact','[]'::jsonb,'before',private.org_preview_visible(before_),'after',private.org_preview_visible(after_),'units',units_,'expires_at',clock_timestamp()+interval '10 minutes');END IF;
 SELECT * INTO p FROM private.org_previews WHERE id=_preview AND actor_id=auth.uid() FOR UPDATE;IF NOT FOUND OR p.applied_at IS NOT NULL OR p.expires_at<=clock_timestamp() OR p.next_transition_at<=clock_timestamp() THEN RAISE EXCEPTION 'Xem trước hết hạn/đã dùng hoặc hiệu lực đã thay đổi.';END IF;IF p.revision<>rev_ OR p.baseline<>fingerprint_ THEN RAISE EXCEPTION 'Nguồn cơ cấu/quyền đã thay đổi; xem trước lại.';END IF;IF coalesce(trim(_reason),'')='' OR _confirmation IS DISTINCT FROM 'ÁP DỤNG CƠ CẤU' THEN RAISE EXCEPTION 'Cần lý do và xác nhận ÁP DỤNG CƠ CẤU.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(p.changes)x WHERE x->>'action' IN ('roles','permissions')) AND _reason NOT LIKE 'ÁP DỤNG PHÂN QUYỀN:%' THEN RAISE EXCEPTION 'Thay đổi quyền cần xác nhận ÁP DỤNG PHÂN QUYỀN: và lý do.';END IF;INSERT INTO private.org_execution(transaction_id,actor_id,preview_id) VALUES(txid_current(),auth.uid(),p.id);units_:=private.org_commands_v2(p.changes);after_:=private.org_config();IF private.org_effect_signature(after_,p.changes) IS DISTINCT FROM p.impact->'signature' THEN RAISE EXCEPTION 'Tác động đã thay đổi; cần xem trước lại.';END IF;INSERT INTO base_org_state(id,revision,config) VALUES(true,rev_+1,after_) ON CONFLICT(id) DO UPDATE SET revision=rev_+1,config=after_,updated_at=now();UPDATE private.org_control SET revision=rev_+1 WHERE id;INSERT INTO org_events(actor_id,before_revision,after_revision,unit_ids,reason,before_data,after_data) VALUES(auth.uid(),rev_,rev_+1,units_,trim(_reason),before_,after_);UPDATE private.org_previews SET applied_at=clock_timestamp() WHERE id=p.id;DELETE FROM private.org_execution WHERE transaction_id=txid_current();RETURN jsonb_build_object('revision',rev_+1);END $$;
REVOKE ALL ON FUNCTION private.org_preview_visible(jsonb) FROM PUBLIC,anon,authenticated,service_role;